function validate(input) {
  const [{ Friends = [] }] = input;
  const seen = new Set();
  for (const [a, b] of Friends) {
    if (a === null || b === null) return 'user1 and user2 cannot be null.';
    if (a === b) return `User ${a} cannot be friends with themselves.`;
    const key = a < b ? `${a},${b}` : `${b},${a}`;
    if (seen.has(key)) return `The pair ${a}, ${b} appears twice.`;
    seen.add(key);
  }
  return null;
}

