function generate(rand, size) {
  const users = size === 'small' ? 2 + Math.floor(rand() * 7) : 90;
  const want = size === 'small' ? Math.floor(rand() * 9) : 1500;
  const base = size === 'small' ? 1 + Math.floor(rand() * 3) * 10 : 1;
  const seen = new Set(), Friends = [];
  for (let tries = 0; Friends.length < want && tries < want * 20; tries++) {
    const a = base + Math.floor(rand() * users), b = base + Math.floor(rand() * users);
    if (a === b) continue;
    const key = a < b ? `${a},${b}` : `${b},${a}`;
    if (seen.has(key)) continue;
    seen.add(key);
    Friends.push([a, b]);
  }
  return [{ Friends }];
}
